// Functions receive shared services and state through an explicit application context.
export function install(ctx){
function listPage(type){const c=type==='clients',data=c?clients:ctx.products;ctx.shell(`${ctx.head(c?'Clientes':'Produtos',c?'Cada relacionamento começa com um bom cadastro.':'Seu catálogo, seus custos e seus preços em um só lugar.',c?'client-new':'product-new',c?'Cadastrar cliente':'Cadastrar produto')}<section class="panel"><div class="panelhead"><h2>${c?'Lista de clientes':'Catálogo de produtos'} <span class="badge">${data.length} registros</span></h2><input id="search" aria-label="Buscar ${c?'cliente':'produto'}" placeholder="Buscar por nome…" type="search"></div><div id="rows"></div></section>`);function draw(s=''){const list=data.filter(x=>(x.name+' '+(x.document||x.sku||'')).toLowerCase().includes(s.toLowerCase()));ctx.$('#rows').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr>${(c?['Cliente','Tipo','CPF / CNPJ','Telefone','E-mail']:['Produto','Código','Custo','Varejo','Atacado']).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${list.map(x=>c?`<tr><td><strong>${ctx.esc(x.name)}</strong></td><td><span class="badge">${x.kind}</span></td><td>${ctx.esc(x.document)||'—'}</td><td>${ctx.esc(x.phone)||'—'}</td><td>${ctx.esc(x.email)||'—'}</td></tr>`:`<tr><td><strong>${ctx.esc(x.name)}</strong></td><td>${ctx.esc(x.sku)||'—'}</td><td>${ctx.money(x.cost)}</td><td>${ctx.money(x.retail)}</td><td>${ctx.money(x.wholesale)}</td></tr>`).join('')}</tbody></table></div>`:ctx.empty(s?'Nenhum resultado encontrado.':c?'Seu primeiro cliente tem lugar aqui.':'Vamos montar seu catálogo?',s?'Tente outro nome.':'Use o botão acima para cadastrar.')}draw();ctx.$('#search').oninput=e=>draw(e.target.value)}

function formPage(page){const c=page==='client-new';ctx.shell(`${ctx.head(c?'Cadastrar cliente':'Cadastrar produto',c?'Dados organizados para propostas mais completas.':'Defina o custo e os preços de referência do produto.')}<section class="panel"><form class="panelbody" id="record-form"><div class="grid2">${c?`<label class="field">Tipo de cliente<select name="kind"><option value="PF">Pessoa física (PF)</option><option value="PJ">Pessoa jurídica (PJ)</option></select></label>${ctx.field('Nome / Razão social','name','text','','required minlength="2" maxlength="200"')}${ctx.field('CPF / CNPJ','document','text','','maxlength="20"')}${ctx.field('Telefone / WhatsApp','phone','tel','','maxlength="25"')}${ctx.field('E-mail','email','email','','maxlength="200"')}${ctx.field('Endereço','address','text','','maxlength="500"')}`:`${ctx.field('Nome do produto','name','text','','required minlength="2" maxlength="200"')}${ctx.field('Código / referência','sku','text','','maxlength="80"')}<div class="span2 grid3">${ctx.field('Custo unitário (R$)','cost','number','','required min="0" max="9999999999" step="0.01"')}${ctx.field('Preço de varejo (R$)','retail','number','','required min="0" max="9999999999" step="0.01"')}${ctx.field('Preço de atacado (R$)','wholesale','number','','required min="0" max="9999999999" step="0.01"')}</div><p class="note span2">Os orçamentos calculam o preço a partir do custo e do percentual escolhido. Varejo e atacado ficam disponíveis como referências do catálogo.</p>`}</div><p id="form-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" id="cancel">Cancelar</button><button type="submit" class="primary">Salvar ${c?'cliente':'produto'}</button></div></form></section>`);ctx.$('#cancel').onclick=()=>ctx.render(c?'clients':'products');ctx.$('#record-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const body=Object.fromEntries(new FormData(e.target));if(!c)for(const k of ['cost','retail','wholesale'])body[k]=Number(body[k]);try{await ctx.api('/rest/v1/'+(c?'clients':'products'),{method:'POST',body,headers:{Prefer:'return=representation'}});await ctx.load();ctx.toast(c?'Cliente cadastrado com sucesso.':'Produto cadastrado com sucesso.');ctx.render(c?'clients':'products')}catch(err){ctx.$('#form-error').className='error';ctx.$('#form-error').textContent=err.message;e.submitter.disabled=false}}}
Object.assign(ctx,{listPage,formPage});
}
